START TRANSACTION;

INSERT INTO `report_templates`
  (`slug`, `name`, `description`, `help_text`, `category`, `sql_template`, `parameters`,
   `data_source`, `execution_config`, `default_limit`, `is_active`, `created_by`)
SELECT
  'marc-field-combination-finder',
  'MARC Field Combination Finder',
  'Finds MARC bibliographic instances that have or are missing several specified field conditions, combined with AND or OR.',
  'Search active locations by campus, library, location name, or location code; select up to 100 locations and choose Effective item or Permanent item as the location basis. Add one to five contiguous MARC conditions and combine them as all conditions (AND) or any condition (OR). A condition can find a matching field occurrence or an instance missing one. Results contain one row per instance and report the conditions evaluated for each row. These findings are facts, not cataloging judgments; review them in the context of record type, cataloging rules, legacy practice, and local policy.',
  'cataloging',
  'WITH target_instances AS MATERIALIZED (
  SELECT
    instance.id AS instance_uuid,
    instance.hrid AS instance_hrid,
    instance.title,
    STRING_AGG(DISTINCT location.name || COALESCE('' ['' || location.code || '']'', ''''), ''; '' ORDER BY location.name || COALESCE('' ['' || location.code || '']'', '''')) AS selected_locations
  {{location_from}}
  WHERE location.id = ANY(string_to_array(:locationIds, '','')::uuid[])
    AND instance.source = ''MARC''
  GROUP BY instance.id, instance.hrid, instance.title
),
matching_instances AS MATERIALIZED (
  SELECT target_instances.*
  FROM target_instances
  WHERE {{active_condition_predicates}}
),
condition_results AS (
  SELECT
    target_instances.instance_uuid,
    {{active_condition_result_expressions}}
  FROM target_instances
  LEFT JOIN {{marc_table_1}} AS condition_1 ON condition_1.instance_id = target_instances.instance_uuid
  LEFT JOIN {{marc_table_2}} AS condition_2 ON condition_2.instance_id = target_instances.instance_uuid
  LEFT JOIN {{marc_table_3}} AS condition_3 ON condition_3.instance_id = target_instances.instance_uuid
  LEFT JOIN {{marc_table_4}} AS condition_4 ON condition_4.instance_id = target_instances.instance_uuid
  LEFT JOIN {{marc_table_5}} AS condition_5 ON condition_5.instance_id = target_instances.instance_uuid
  GROUP BY target_instances.instance_uuid
)
SELECT * FROM matching_instances
ORDER BY "Title" NULLS LAST, "Instance HRID" NULLS LAST, "Instance UUID"
LIMIT 100001',
  '[{"name":"locationIds","type":"multiselect","label":"Locations","required":true,"default":"","placeholder":"Search locations","description":"Active FOLIO locations used to scope candidate bibliographic records.","max_selections":100,"groupSelect":true,"options_db":"folio","options_sql":"SELECT loc.id AS value, COALESCE(campus.name || '' — '', '''') || COALESCE(lib.name || '' — '', '''') || loc.name || COALESCE('' ['' || loc.code || '']'', '''') AS label FROM inventory.location__t loc LEFT JOIN inventory.loclibrary__t lib ON lib.id = loc.library_id LEFT JOIN inventory.loccampus__t campus ON campus.id = lib.campus_id WHERE COALESCE(loc.is_active, true) ORDER BY campus.name, lib.name, loc.name, loc.code"},{"name":"locationBasis","type":"select","label":"Location basis","required":true,"default":"effective_item","options_db":"folio","options_sql":"SELECT value, label FROM (VALUES (''effective_item'', ''Effective item''), (''permanent_item'', ''Permanent item'')) AS basis(value, label)"},{"name":"combine","type":"select","label":"Combine conditions","required":true,"default":"all","options":[{"value":"all","label":"All conditions (AND)"},{"value":"any","label":"Any condition (OR)"}]},{"name":"c1_marcTag","type":"text","label":"Condition 1 MARC tag","required":true,"default":"","placeholder":"655","input_mode":"numeric","pattern":"[0-9]{3}","max_length":3},{"name":"c1_occurrenceCondition","type":"select","label":"Condition 1 occurrence condition","required":false,"default":"has","options":[{"value":"has","label":"Has matching occurrence"},{"value":"missing","label":"Missing matching occurrence"}]},{"name":"c1_firstIndicator","type":"select","label":"Condition 1 first indicator","required":false,"default":"any","options":[{"value":"any","label":"Any"},{"value":"blank","label":"Blank (#)"},{"value":"char:0","label":"0"},{"value":"char:1","label":"1"},{"value":"char:2","label":"2"},{"value":"char:3","label":"3"},{"value":"char:4","label":"4"},{"value":"char:5","label":"5"